if(!EditorApplication.isPlaying)throw new System.Exception("Enter fresh Save01 Play first.");
var p=GameObject.Find("Player");var save=p.GetComponent<PrisonGame.Prototype.SampleSaveGame>();var actor=p.GetComponent<PrisonGame.Prototype.PlayerInteraction>();var stock=p.GetComponent<PrisonGame.Prototype.SnackSupplies>();var request=p.GetComponent<PrisonGame.Prototype.SnackRequest>();var clock=request.Clock;var tray=UnityEngine.Object.FindFirstObjectByType<PrisonGame.Prototype.SnackAssembly>();var shelf=UnityEngine.Object.FindFirstObjectByType<PrisonGame.Prototype.SnackShelf>();var inspection=UnityEngine.Object.FindFirstObjectByType<PrisonGame.Prototype.SupplyInspection>();var guard=p.GetComponent<PrisonGame.Prototype.GuardSuspicion>();
