Check(stock.Money==3 && stock.Sales==1 && stock.Crackers==0 && stock.Fruit==1 && stock.Wrappers==1,"Money, sale count and consumed ingredients restore exactly");
Check(request.Accepted && request.Delivered==1 && request.Paid==3 && request.DueAt==state.player.dueAt,"Request delivery, payment and original deadline restore");
Check(tray.Stage==1 && tray.WorkingPlayer==actor,"Unfinished tray restores its working player");
Check(actor.HeldItem==parcel && !parcel.GetComponent<Collider>().enabled,"Carried parcel restores attachment and disabled collision");
Check(Vector3.Distance(p.transform.position,state.player.position)<.001f && Quaternion.Angle(p.transform.rotation,Quaternion.Euler(0,110,0))<.01f,"Player position and yaw restore");
Check(Quaternion.Angle(p.GetComponentInChildren<Camera>().transform.localRotation,Quaternion.Euler(-15,0,0))<.01f,"Camera pitch restores");
Check(guard.Level==55 && inspection.Closed && inspection.ReopensAt==state.world.reopensAt,"Suspicion and active closure restore");
Check(clock.Paused && Time.timeScale==0 && !p.GetComponent<PrisonGame.Prototype.FirstPersonController>().ControlsActive,"Loading stays paused with mouse released");
