state=save.Capture(actor);state.world.parcels[0].held=false;state.world.parcels[0].position=new Vector3(-4,1,-1);save.Restore(actor,state);
tray.Interact(actor);tray.Interact(actor);Check(actor.HeldItem!=null && actor.HeldItem.GetComponent<PrisonGame.Prototype.SnackPackItem>()!=null,"Loaded unfinished tray can produce a usable pack");
var held=save.Capture(actor);
var stored=JsonUtility.FromJson<PrisonGame.Prototype.SampleSaveData>(JsonUtility.ToJson(held));stored.world.shelfInstalled=true;stored.world.packs[0].held=false;stored.world.packs[0].position=new Vector3(-3.08f,1.55f,-2.85f);stored.world.packs[0].velocity=new Vector3(.1f,0,0);stored.world.doors[0].opening=true;stored.world.doors[0].position+=Vector3.forward*.5f;
save.Restore(actor,stored);var storedAgain=save.Capture(actor);
Check(actor.HeldItem==null && request.ReadyPacks==1 && Vector3.Distance(storedAgain.world.packs[0].position,stored.world.packs[0].position)<.001f,"Stored pack restores world position and ready-pack count");
Check(storedAgain.world.packs[0].velocity==stored.world.packs[0].velocity && storedAgain.world.doors[0].opening && storedAgain.world.doors[0].position==stored.world.doors[0].position,"Item velocity and partially opened door restore");
save.Restore(actor,fresh);save.Restore(actor,held);save.Restore(actor,held);
Check(request.ReadyPacks==1 && actor.HeldItem.GetComponent<PrisonGame.Prototype.SnackPackItem>().Source==stock,"Repeated load neither duplicates held packs nor loses their owner");
