clock.SetPaused(false);clock.Advance(50);clock.SetPaused(true);bool free;stock.Restock(out free);for(int i=0;i<3;i++)tray.Interact(actor);request.Deliver(actor,request.Customer);shelf.Interact(actor);
Check(request.Complete && stock.Money==0 && shelf.Installed && !inspection.Closed,"Loaded loop remains completable through shelf purchase");
var completed=save.Capture(actor);save.Restore(actor,fresh);save.Restore(actor,completed);Check(shelf.Installed && request.Complete && request.Paid==9 && stock.Money==0,"Completion, actual payment and purchased shelf restore");
