bad=JsonUtility.FromJson<PrisonGame.Prototype.SampleSaveData>(before);bad.scene="OtherScene";System.IO.File.WriteAllText("Temp/Save01Checks/bad.json",JsonUtility.ToJson(bad));Check(!save.LoadFrom(actor,"Temp/Save01Checks/bad.json"),"Another scene's save is rejected");
